<!-- This file is generated by AI. -->
<!--
  Git 差异编辑器: Monaco 的 DiffEditor 宿主。

  生命周期有一个顺序约束: 销毁时**必须先 dispose editor 再 dispose 两个 model** —— 反过来的话
  diff editor 会拿着已销毁的 model 再画一帧, 直接抛异常。
-->
<script lang="ts">
  import * as monaco from 'monaco-editor';
  import { untrack } from 'svelte';

  import { gitCommitDiff, gitDiff } from '../commands/git';
  import { languageForPath } from '../lsp/monaco';
  import { appStore } from '../state/store.svelte';
  import { watchValues } from '../state/watch.svelte';
  import type { DiffTab } from '../tabs/model';

  let { tab }: { tab: DiffTab } = $props();

  let host: HTMLDivElement | undefined = $state();
  let message = $state<string | null>(null);

  const settings = $derived(appStore.settings);

  const diffOptions = $derived<monaco.editor.IStandaloneDiffEditorConstructionOptions>({
    renderSideBySide: settings.gitDiffView === 'sideBySide',
    readOnly: true,
    automaticLayout: true,
    minimap: { enabled: false },
    fontFamily: settings.editorFontFamily,
    fontSize: settings.editorFontSize,
    // 不设 `scrollBeyondLastLine`: Monaco 默认 true, 与 CodeEditor 保持一致
    renderOverviewRuler: false,
    // 两个 model 都按只读用, 因此不显示"交换/还原"这类动作
    originalEditable: false,
    /*
     * 补全/悬浮等浮层挂到 body 上, 而不是留在编辑器容器里: 容器的 `overflow: hidden` 会把
     * 它们裁掉 (靠边的浮层只显示一半)。`ui/PreprocessTab.svelte` 也要设这一项。
     */
    fixedOverflowWidgets: true,
  });

  /** 差异内容按选项卡身份取一次; 切换选项卡时整个组件重建 (父级按 tab.id 区分)。 */
  $effect(() => {
    const projectPath = appStore.projectPath;
    if (!host || !projectPath) return;

    const { file, diffKind, commitId, options } = untrack(() => ({
      file: tab.file,
      diffKind: tab.diffKind,
      commitId: tab.commitId,
      options: diffOptions,
    }));

    let disposed = false;
    /** 先建好再挂, 保证 cleanup 里拿到的是同一批对象 */
    let diffEditor: monaco.editor.IStandaloneDiffEditor | null = null;
    let original: monaco.editor.ITextModel | null = null;
    let modified: monaco.editor.ITextModel | null = null;

    const uriBase = `inmemory://git-diff/${diffKind}/${commitId ?? ''}/${file.replace(/[\\/]/g, '-')}`;

    diffEditor = monaco.editor.createDiffEditor(host, options);
    // 建 model 时就带上正确语言: 先建 plaintext 再 setModelLanguage 会先以无高亮画一帧
    const language = languageForPath(file);
    original = monaco.editor.createModel('', language, monaco.Uri.parse(`${uriBase}?original`));
    modified = monaco.editor.createModel('', language, monaco.Uri.parse(`${uriBase}?modified`));
    diffEditor.setModel({ original, modified });

    const settingsWatcher = watchValues({
      select: () => [appStore.settings.gitDiffView],
      onChange: () => {
        const next = appStore.settings.gitDiffView;
        diffEditor?.updateOptions({ renderSideBySide: next === 'sideBySide' });
      },
    });

    void (async () => {
      try {
        const diff =
          diffKind === 'commit' && commitId
            ? await gitCommitDiff(projectPath, file, commitId)
            : await gitDiff(projectPath, file, diffKind === 'staged' ? 'staged' : 'unstaged');
        if (disposed) return;
        if (diff.binary) {
          message = '二进制文件，无法展示文本差异';
          return;
        }
        message = null;
        // 语言按文件类型判定, 让差异也有高亮
        const language = languageForFile(file);
        original?.setValue(diff.original ?? '');
        modified?.setValue(diff.modified ?? '');
        if (original) monaco.editor.setModelLanguage(original, language);
        if (modified) monaco.editor.setModelLanguage(modified, language);
      } catch (error) {
        if (!disposed) message = `无法加载差异：${String(error)}`;
      }
    })();

    return () => {
      disposed = true;
      settingsWatcher.stop();
      // 顺序不能反: 先 editor 再 model
      diffEditor?.dispose();
      original?.dispose();
      modified?.dispose();
    };
  });

  /*
   * 差异两侧的语言 = **代码编辑器同一套判据** (`lsp/monaco.ts` 的 `languageForPath`)。
   *
   * 不要在这里另写一份"只看扩展名"的判据: 那会把 `.txt` 判成 `plaintext`, 而场景文件正是
   * `.txt` —— 场景的差异选项卡两边都没有高亮。复制一份判据必然会再次漂移。
   */
  function languageForFile(file: string): string {
    return languageForPath(file);
  }
</script>

<div class="git-diff-host" bind:this={host}></div>

{#if message}
  <p class="editor-empty git-diff-message">{message}</p>
{/if}
